package com.careerassistant.dashboard;
import com.careerassistant.resume.ResumeRepository;import com.careerassistant.security.CurrentUser;import com.careerassistant.tracker.*;import jakarta.persistence.EntityManager;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController{
 private final JobApplicationRepository applications;private final ResumeRepository resumes;private final EntityManager em;
 public DashboardController(JobApplicationRepository a,ResumeRepository r,EntityManager e){applications=a;resumes=r;em=e;}
 @GetMapping("/summary") public Map<String,Object> summary(){Long userId=CurrentUser.require().getId();Map<String,Long> byStatus=new LinkedHashMap<>();for(ApplicationStatus status:ApplicationStatus.values())byStatus.put(status.name(),applications.countByUserIdAndStatus(userId,status));long interviews=em.createQuery("select count(i) from InterviewSession i where i.user.id=:id",Long.class).setParameter("id",userId).getSingleResult();long completed=em.createQuery("select count(t) from RoadmapTask t where t.roadmap.user.id=:id and t.status='COMPLETED'",Long.class).setParameter("id",userId).getSingleResult();long tasks=em.createQuery("select count(t) from RoadmapTask t where t.roadmap.user.id=:id",Long.class).setParameter("id",userId).getSingleResult();List<JobApplication> upcoming=applications.findByUserIdOrderByApplicationDateDesc(userId).stream().filter(a->a.getInterviewDate()!=null&&a.getInterviewDate().isAfter(LocalDateTime.now())).sorted(Comparator.comparing(JobApplication::getInterviewDate)).limit(5).toList();return Map.of("totalApplications",applications.findByUserIdOrderByApplicationDateDesc(userId).size(),"statusCounts",byStatus,"resumeCount",resumes.findByUserIdOrderByCreatedAtDesc(userId).size(),"interviewSessions",interviews,"learningProgress",tasks==0?0:(int)(100*completed/tasks),"upcomingInterviews",upcoming.stream().map(a->Map.of("company",a.getCompany(),"position",a.getPosition(),"date",a.getInterviewDate())).toList());}
}
